package dev.koikaster.mite;
import java.util.*;import net.minecraft.core.*;import net.minecraft.server.level.*;import net.minecraft.tags.BiomeTags;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.entity.animal.*;import net.minecraft.world.entity.animal.horse.AbstractHorse;import net.minecraft.world.entity.monster.Monster;import net.minecraft.world.level.*;import net.minecraft.world.level.biome.*;import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraftforge.event.TickEvent;import net.minecraftforge.event.entity.EntityJoinLevelEvent;import net.minecraftforge.event.entity.living.LivingEvent;import net.minecraftforge.event.entity.player.PlayerEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.eventbus.api.EventPriority;import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid=MiteReforged.ID)
public final class LocalWeather1981 {
 public enum Kind {NONE,SANDSTORM,MOUNTAIN_FOG,BLIZZARD}
 public record State(Kind kind,float strength){}
 public static final State NONE=new State(Kind.NONE,0);private static final UUID VISIBILITY=UUID.fromString("69d7f4b2-1981-4a87-8457-ae3d6423b501");
 public static boolean exposed(Level level,BlockPos pos){return level.getFluidState(pos).isEmpty()&&level.canSeeSky(pos)&&level.getHeight(Heightmap.Types.MOTION_BLOCKING,pos.getX(),pos.getZ())<=pos.getY();}
 public static State regional(ServerLevel level,BlockPos pos){if(!WorldContentMode.rebuilt(level)||level.dimension()!=Level.OVERWORLD||!level.getGameRules().getBoolean(GameRules.RULE_WEATHER_CYCLE)||!level.hasChunkAt(pos))return NONE;float strength=LocalWeatherPlan1981.strength(level.getSeed(),level.getDayTime(),pos.getX(),pos.getZ());if(strength<=.001f)return NONE;var biome=level.getBiome(pos);Kind kind;if(biome.is(Biomes.DESERT)||biome.is(BiomeTags.IS_BADLANDS))kind=Kind.SANDSTORM;else if(biome.value().getPrecipitationAt(pos)==Biome.Precipitation.SNOW)kind=Kind.BLIZZARD;else if(pos.getY()>=96&&biome.is(BiomeTags.IS_MOUNTAIN))kind=Kind.MOUNTAIN_FOG;else return NONE;return new State(kind,strength);}
 public static State at(ServerLevel level,BlockPos pos){return exposed(level,pos)?regional(level,pos):NONE;}
 public static boolean preventsDrying(Level level,BlockPos pos){if(!(level instanceof ServerLevel server))return false;var state=regional(server,pos);return state.kind()==Kind.BLIZZARD&&state.strength()>.08f;}
 private static void sync(ServerPlayer player){var state=at(player.serverLevel(),BlockPos.containing(player.getX(),player.getEyeY(),player.getZ()));LocalWeatherTransport1981.send(player,state);}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent event){if(event.phase!=TickEvent.Phase.END)return;var server=net.minecraftforge.server.ServerLifecycleHooks.getCurrentServer();if(server!=null&&server.getTickCount()%20==0)for(var player:server.getPlayerList().getPlayers())sync(player);}
 @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(event.getEntity() instanceof ServerPlayer player)sync(player);}
 @SubscribeEvent public static void changed(PlayerEvent.PlayerChangedDimensionEvent event){if(event.getEntity() instanceof ServerPlayer player)sync(player);}
 @SubscribeEvent public static void living(LivingEvent.LivingTickEvent event){if(!(event.getEntity() instanceof Monster mob)||mob instanceof net.minecraft.world.entity.boss.wither.WitherBoss||!(mob.level() instanceof ServerLevel level)||level.getGameTime()%40!=0)return;var attribute=mob.getAttribute(Attributes.FOLLOW_RANGE);if(attribute==null)return;var state=at(level,BlockPos.containing(mob.getX(),mob.getEyeY(),mob.getZ()));double amount=state.kind()==Kind.NONE?0:-.25*state.strength();var previous=attribute.getModifier(VISIBILITY);if(previous!=null&&amount!=0&&Math.abs(previous.getAmount()-amount)<.005)return;if(previous!=null)attribute.removeModifier(VISIBILITY);if(amount<-.001)attribute.addTransientModifier(new AttributeModifier(VISIBILITY,"weather",amount,AttributeModifier.Operation.MULTIPLY_TOTAL));}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void joining(EntityJoinLevelEvent event){if(event.getLevel().isClientSide||!WorldContentMode.rebuilt(event.getLevel())||!(event.getEntity() instanceof PathfinderMob mob)||!(mob instanceof Cow||mob instanceof Pig||mob instanceof Sheep||mob instanceof Chicken||mob instanceof Rabbit||mob instanceof AbstractHorse))return;var goals=((SourceMobAi)mob).mite$goals();if(goals.getAvailableGoals().stream().noneMatch(g->g.getGoal() instanceof ShelterWeatherGoal1981))goals.addGoal(3,new ShelterWeatherGoal1981(mob));}
 private LocalWeather1981(){}
}
